INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (356, 1, '플레이버가 정하는 것', 'OpenStack 에서 서버를 만들 때 고르는 **플레이버(flavor)** 는 무엇을 정할까요?', '티셔츠의 S·M·L 사이즈처럼 크기를 고르는 거예요.', NULL, NULL, '[]', 'choice', '["서버가 처음 부팅할 운영체제의 종류와 버전", "서버가 연결될 가상 네트워크와 서브넷 이름", "서버 크기: vCPU 수, 메모리, 루트 디스크 용량", "서버에 접속할 수 있는 사용자와 권한 목록"]', 2, '플레이버는 서버의 하드웨어 구성(크기)을 정합니다. 필수 항목은 vCPU 수, 메모리(RAM), 루트 디스크 크기입니다. 운영체제는 이미지가 정합니다.', NULL, NULL, NULL, '[{"title": "Nova 플레이버", "url": "https://docs.openstack.org/nova/latest/user/flavors.html"}]'),
  (356, 2, '부팅에 쓰는 것은 이미지', '서버를 만들 때 **어떤 운영체제로 부팅할지** 는 무엇으로 정할까요?', '서버가 시작할 때 복사해 쓰는 템플릿이에요.', NULL, NULL, '[]', 'choice', '["플레이버(서버의 크기를 고르는 선택지)", "이미지(Glance 에 등록된 디스크 이미지)", "키페어(SSH 접속에 쓰는 열쇠 한 쌍)", "보안 그룹(들어오는 트래픽을 거르는 규칙)"]', 1, '서버의 소스는 이미지에서 부팅하는 것이 기본입니다. 공식 문서는 인스턴스 소스가 이미지, 스냅샷, 또는 이미지나 스냅샷이 든 블록 스토리지 볼륨일 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 3, '인스턴스 소스가 될 수 있는 것', '공식 문서가 말하는 **인스턴스 소스**(서버를 시작할 때 쓰는 원본)로 알맞은 것은 무엇일까요?', '이미지만 되는 게 아니에요.', NULL, NULL, '[]', 'choice', '["이미지, 스냅샷, 또는 이미지가 담긴 볼륨", "오직 이미지 한 가지만 소스가 될 수 있다", "플레이버와 보안 그룹을 합친 조합 하나", "키페어와 사용자 데이터 파일 한 쌍"]', 0, 'Nova 문서는 "인스턴스 소스는 이미지, 스냅샷, 또는 이미지나 스냅샷이 담긴 블록 스토리지 볼륨"이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 4, '키페어는 무엇을 위한 것일까', '서버를 만들 때 **키페어** 를 지정하는 이유로 알맞은 것은 무엇일까요?', '비밀번호 대신 열쇠로 들어가는 방식이에요.', NULL, NULL, '[]', 'choice', '["서버의 CPU 속도를 더 높게 올려 주려고", "서버의 디스크 용량을 자동으로 늘려 주려고", "서버의 이름을 규칙에 따라 자동으로 정하려고", "서버 시작 때 SSH 접속용 키를 넣어 그 키로 접속하려고"]', 3, '키페어는 서버가 시작될 때 이미지에 주입되는 SSH 자격 증명입니다. 주입이 되려면 이미지에 cloud-init 이 있어야 한다고 문서가 안내합니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 5, '보안 그룹은 무엇을 정할까', '**보안 그룹** 이 정하는 것으로 알맞은 것은 무엇일까요?', '건물 출입문의 출입 규칙과 비슷해요.', NULL, NULL, '[]', 'choice', '["서버가 쓸 수 있는 메모리의 최대 양과 한도", "서버를 만들 수 있는 사용자의 이름과 목록", "서버로 들어오는 트래픽 중 무엇을 허용할지", "서버에 설치될 운영체제의 종류와 버전 정보"]', 2, '문서는 보안 그룹을 "어떤 들어오는 네트워크 트래픽을 인스턴스로 전달할지 정하는 것"이라고 설명합니다. 기본 보안 그룹은 규칙을 바꾸지 않으면 클라우드 밖에서의 접근을 허용하지 않습니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 6, 'SSH 가 안 될 때 먼저 볼 것', '서버는 ACTIVE 인데 밖에서 SSH 로 접속이 **안 됩니다**. 문서의 설명에 비추어 먼저 확인할 것으로 알맞은 것은 무엇일까요?', '문을 열어 주는 규칙이 있는지 보세요.', NULL, NULL, '[]', 'choice', '["플레이버의 이름이 맞는지", "보안 그룹에 접속을 허용하는 규칙이 있는지", "이미지가 Glance 에 등록된 날짜", "서버의 이름에 숫자가 들어 있는지"]', 1, '기본 보안 그룹은 규칙을 바꾸지 않으면 외부에서의 접근을 허용하지 않습니다. SSH 용 규칙(22번 포트)이 허용되어 있는지 확인하는 것이 먼저입니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 7, '사용자 데이터란', '서버를 만들 때 넘길 수 있는 **사용자 데이터(user data)** 는 무엇일까요?', '서버가 첫 부팅 때 읽어 가는 쪽지 같은 거예요.', NULL, NULL, '[]', 'choice', '["메타데이터 서비스로 서버 안 프로그램이 읽어 가는 데이터", "서버 디스크에 영구 저장되는 별도 데이터 볼륨", "서버를 만들 수 있는 사용자들의 목록 데이터", "서버 사용료를 계산하는 데 쓰는 청구용 데이터"]', 0, '문서는 사용자 데이터를 메타데이터 서비스의 특별한 키로 설명하며, cloud-init 같은 클라우드 인식 프로그램이 읽을 수 있습니다. 첫 부팅 시 초기 설정을 자동화할 때 씁니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 8, '플로팅 IP 를 붙이는 때', '서버를 만든 **뒤에** 외부에서 접근해야 할 때 문서가 안내하는 단계로 알맞은 것은 무엇일까요?', '이름 그대로 서버에 붙였다 뗐다 하는 주소예요.', NULL, NULL, '[]', 'choice', '["서버를 만들기 전에 반드시 플로팅 IP 를 보안 그룹에 등록한다", "플로팅 IP 가 있으면 보안 그룹은 필요 없어진다", "플로팅 IP 는 서버를 삭제한 뒤에만 쓸 수 있다", "서버가 외부 접근이 필요할 때 만든 뒤에 플로팅 IP 를 할당한다"]', 3, '문서는 플로팅 IP 를 선택 사항으로, 외부 접근이 필요할 때 서버를 시작한 뒤 할당하는 것으로 설명합니다. 보안 그룹 규칙도 함께 허용되어야 접속됩니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 9, '플레이버는 누가 만들까', '서버 크기를 정의하는 **플레이버** 를 새로 만드는 일은 보통 누가 할까요?', '일반 사용자는 있는 것 중에서 골라 써요.', NULL, NULL, '[]', 'choice', '["서버를 만드는 일반 사용자 모두", "서버에 접속하는 외부 방문자", "관리자(administrator)", "이미지를 받는 컴퓨트 노드의 하이퍼바이저"]', 2, 'Nova 문서는 플레이버를 만드는 일이 보통 관리자의 일이라고 설명합니다. 사용자는 목록(`openstack flavor list`)에서 알맞은 크기를 골라 씁니다.', NULL, NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 10, '키페어 지정하기', '서버를 만들 때 **키페어 이름** 을 지정하는 옵션입니다. 빈칸을 채우세요.', '키(key)와 이름(name)이 들어가는 옵션이에요.', NULL, NULL, '[]', 'fill', '["--key-name", "--keypair", "--ssh", "--key-file"]', NULL, '`--key-name` 으로 서버에 주입할 키페어의 이름을 지정합니다. 키페어는 프로젝트에 미리 등록해 두어야 합니다.', '[0]', 'openstack server create --flavor m1.small --image cirros {0} mykey web1', NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]'),
  (356, 11, '플레이버 목록 보기', '쓸 수 있는 **플레이버 목록** 을 보는 명령입니다. 빈칸을 채우세요.', '크기 선택지를 보여 달라는 거예요.', NULL, NULL, '[]', 'fill', '["flavor", "size", "type", "spec"]', NULL, '`openstack flavor list` 로 사용할 수 있는 플레이버(vCPU, RAM, 디스크 크기)를 확인합니다.', '[0]', 'openstack {0} list', NULL, '[{"title": "Nova 플레이버", "url": "https://docs.openstack.org/nova/latest/user/flavors.html"}]'),
  (356, 12, '서버를 만들기 전에 확인하는 순서', '서버를 만들기 전에 준비물을 확인하고 만든 뒤 상태까지 보는 순서입니다. 순서에 맞게 놓아 보세요.', '목록 확인 → 만들기 → 상태 확인 순서예요.', NULL, NULL, '[]', 'order', '["쓸 수 있는 플레이버 목록을 본다", "쓸 수 있는 이미지 목록을 본다", "보안 그룹과 키페어 이름을 확인한다", "`openstack server create` 로 서버를 만든다", "상태가 ACTIVE 가 되었는지 확인한다"]', NULL, '문서의 절차는 플레이버·이미지·보안 그룹·키페어 목록을 확인한 뒤 서버를 만드는 순서입니다. 만든 뒤에는 상태가 ACTIVE 가 되었는지 확인합니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "인스턴스 만들기", "url": "https://docs.openstack.org/nova/latest/user/launch-instances.html"}]');
